//! # bury
//!
//! A secure CLI helper for encrypting and decrypting secrets for shell usage.
//!
//! ## Overview
//! - Secrets are encrypted with XChaCha20-Poly1305 using a key derived from a
//!   user-provided passphrase via Argon2id.
//! - The passphrase is stored in the macOS Keychain (via `keyring`) after the
//!   first prompt, so it is not embedded in the binary or config files.
//! - The output format is `bury:v1:<base64(salt||nonce||ciphertext)>`.
//!
//! ## Security Model
//! - Protects against accidental leaks (dotfiles, backups, git history).
//! - Resistant to offline brute-force using a memory-hard KDF.
//! - Does not claim to defeat a fully privileged attacker who can inspect the
//!   running process or the OS keychain.
//!
//! ## Usage
//! - `bury --encrypt "plaintext"` -> prints ciphertext
//! - `bury "ciphertext"` -> prints plaintext
//! - `bury --setup` -> prompts and stores passphrase in Keychain
//! - `bury --clear-secret` -> deletes stored passphrase
//!
//! ## Notes
//! - All sensitive buffers are zeroized on drop.
//! - No secrets are logged or written to disk.

use std::fmt;
use std::io::{self, Read, Write};

use argon2::{Algorithm, Argon2, Params, Version};
use base64::Engine as _;
use chacha20poly1305::aead::{Aead, KeyInit};
use chacha20poly1305::{XChaCha20Poly1305, XNonce};
use clap::Parser;
use keyring::Entry;
use rand::RngCore;
use rand::rngs::OsRng;
use thiserror::Error;
use tracing::{debug, info, warn};
use tracing_subscriber::EnvFilter;
use zeroize::{Zeroize, ZeroizeOnDrop};

const KEYCHAIN_SERVICE: &str = "bury-secret";
const DERIVED_KEY_CACHE_SERVICE: &str = "bury-v1-derived-key-cache";
const FORMAT_PREFIX: &str = "bury:v1:";
const SALT_LEN: usize = 16;
const NONCE_LEN: usize = 24;
const DERIVED_KEY_LEN: usize = 32;
const DERIVED_KEY_CACHE_MAGIC: &[u8] = b"bury-cache:v1\0";
const DERIVED_KEY_CACHE_RECORD_LEN: usize = SALT_LEN + DERIVED_KEY_LEN;

/// Argon2id parameters.
///
/// - Memory: 64 MiB
/// - Iterations: 3
/// - Parallelism: 1
const ARGON2_ALGORITHM: Algorithm = Algorithm::Argon2id;
const ARGON2_VERSION: Version = Version::V0x13;

#[derive(Parser, Debug)]
#[command(
    name = "bury",
    version,
    about = "Encrypt/decrypt secrets for shell usage"
)]
struct Cli {
    /// Encrypt a plaintext string.
    #[arg(long, value_name = "PLAINTEXT", conflicts_with_all = ["ciphertext", "setup", "clear_secret", "encrypt_stdin", "encrypt_env"]) ]
    encrypt: Option<String>,

    /// Encrypt plaintext read from stdin.
    #[arg(long, conflicts_with_all = ["ciphertext", "setup", "clear_secret", "encrypt", "encrypt_env"]) ]
    encrypt_stdin: bool,

    /// Encrypt plaintext read from environment variable.
    #[arg(long, value_name = "ENV_VAR", conflicts_with_all = ["ciphertext", "setup", "clear_secret", "encrypt", "encrypt_stdin"]) ]
    encrypt_env: Option<String>,

    /// Setup: prompt for passphrase and store in Keychain.
    #[arg(long, conflicts_with_all = ["encrypt", "ciphertext", "clear_secret"]) ]
    setup: bool,

    /// Clear stored passphrase from Keychain.
    #[arg(long, conflicts_with_all = ["encrypt", "ciphertext", "setup"]) ]
    clear_secret: bool,

    /// Ciphertext to decrypt (positional).
    ciphertext: Option<String>,
}

#[derive(Error, Debug)]
enum BuryError {
    #[error("invalid input: {0}")]
    InvalidInput(String),
    #[error("decryption failed")]
    DecryptionFailed,
    #[error("keychain error: {0}")]
    Keychain(#[from] keyring::Error),
    #[error("io error: {0}")]
    Io(#[from] io::Error),
    #[error("base64 decode error: {0}")]
    Base64(#[from] base64::DecodeError),
    #[error("crypto error: {0}")]
    Crypto(String),
}

#[derive(ZeroizeOnDrop)]
struct SecretString {
    value: String,
}

/// Parsed `bury:v1:` payload components.
///
/// The struct owns the decoded ciphertext buffer so the caller can validate the
/// envelope once, inspect the salt for cache lookup, and then attempt
/// decryption without repeating base64 parsing.
///
/// Security considerations:
/// - The salt is not secret and is safe to reuse as a cache lookup key.
/// - The ciphertext bytes remain authenticated by XChaCha20-Poly1305 and are
///   never trusted without successful decryption.
#[derive(Debug, Clone)]
struct ParsedCiphertext {
    salt: [u8; SALT_LEN],
    nonce: [u8; NONCE_LEN],
    ciphertext: Vec<u8>,
}

/// One cache record stored in the Keychain-backed derived-key cache.
///
/// Each record binds a v1 ciphertext salt to the corresponding Argon2-derived
/// symmetric key. Caching the derived key preserves the original security
/// boundary of "dotfiles alone cannot decrypt" because the cache remains inside
/// the OS credential store rather than on disk, while removing repeated Argon2
/// work during steady-state shell startup.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct DerivedKeyCacheRecord {
    salt: [u8; SALT_LEN],
    key: [u8; DERIVED_KEY_LEN],
}

impl SecretString {
    fn new(value: String) -> Self {
        Self { value }
    }

    fn as_bytes(&self) -> &[u8] {
        self.value.as_bytes()
    }
}

impl fmt::Debug for SecretString {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("SecretString(<redacted>)")
    }
}

fn main() -> Result<(), BuryError> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .with_target(false)
        .init();

    let cli = Cli::parse();

    if cli.setup {
        setup_secret()?;
        return Ok(());
    }

    if cli.clear_secret {
        clear_secret()?;
        return Ok(());
    }

    if let Some(plaintext) = cli.encrypt.as_deref() {
        let plaintext = SecretString::new(plaintext.to_string());
        let secret = load_or_prompt_secret()?;
        let ciphertext = encrypt_secret(plaintext.as_bytes(), secret.as_bytes())?;
        println!("{ciphertext}");
        return Ok(());
    }

    if cli.encrypt_stdin {
        let plaintext = read_plaintext_from_stdin()?;
        let secret = load_or_prompt_secret()?;
        let ciphertext = encrypt_secret(plaintext.as_bytes(), secret.as_bytes())?;
        println!("{ciphertext}");
        return Ok(());
    }

    if let Some(env_var) = cli.encrypt_env.as_deref() {
        let plaintext = read_plaintext_from_env(env_var)?;
        let secret = load_or_prompt_secret()?;
        let ciphertext = encrypt_secret(plaintext.as_bytes(), secret.as_bytes())?;
        println!("{ciphertext}");
        return Ok(());
    }

    let ciphertext = cli
        .ciphertext
        .ok_or_else(|| BuryError::InvalidInput("ciphertext is required".to_string()))?;
    let parsed = parse_ciphertext(&ciphertext)?;
    let plaintext = decrypt_ciphertext_with_cache(&parsed)?;
    io::stdout().write_all(&plaintext)?;
    Ok(())
}

/// Construct a Keychain entry for the current macOS user.
///
/// The cache and passphrase entries both use the current username as the
/// account identifier so the credential namespace is scoped to the invoking
/// user. This mirrors the original design while keeping the storage lookup
/// deterministic and local-only.
///
/// Returns:
/// - `Ok(Entry)` when the Keychain entry metadata can be constructed.
/// - `Err(BuryError::Keychain)` if the underlying credential backend rejects
///   the service/account pair.
fn keychain_entry_for_service(service: &str) -> Result<Entry, BuryError> {
    let username = whoami::username();
    Entry::new(service, &username).map_err(BuryError::Keychain)
}

/// Return the Keychain entry that stores the primary v1 passphrase.
fn secret_entry() -> Result<Entry, BuryError> {
    keychain_entry_for_service(KEYCHAIN_SERVICE)
}

/// Return the Keychain entry that stores cached v1 derived keys.
fn derived_key_cache_entry() -> Result<Entry, BuryError> {
    keychain_entry_for_service(DERIVED_KEY_CACHE_SERVICE)
}

fn read_plaintext_from_stdin() -> Result<SecretString, BuryError> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let trimmed = input.trim_end_matches(['\n', '\r']);
    if trimmed.is_empty() {
        return Err(BuryError::InvalidInput(
            "stdin plaintext is empty".to_string(),
        ));
    }
    Ok(SecretString::new(trimmed.to_string()))
}

fn read_plaintext_from_env(var_name: &str) -> Result<SecretString, BuryError> {
    let value = std::env::var(var_name).map_err(|_| {
        BuryError::InvalidInput(format!("environment variable '{var_name}' not set"))
    })?;
    if value.is_empty() {
        return Err(BuryError::InvalidInput(format!(
            "environment variable '{var_name}' is empty"
        )));
    }
    Ok(SecretString::new(value))
}

fn setup_secret() -> Result<(), BuryError> {
    let secret = prompt_secret("Enter passphrase for bury: ")?;
    let entry = secret_entry()?;
    entry.set_password(&secret.value)?;
    let cache_entry = derived_key_cache_entry()?;
    match cache_entry.delete_credential() {
        Ok(()) | Err(keyring::Error::NoEntry) => {}
        Err(err) => return Err(BuryError::Keychain(err)),
    }
    info!("Passphrase stored in Keychain");
    Ok(())
}

/// Clear both the stored passphrase and any cached derived keys.
///
/// Purpose:
/// - Restores the original "prompt on first use" state for v1 secrets.
/// - Ensures the performance cache does not outlive an explicit user request to
///   remove key material from the Keychain.
///
/// Error handling:
/// - Missing entries are ignored so repeated clears remain idempotent.
/// - Any other Keychain error aborts the operation and is surfaced to the
///   caller.
fn clear_secret() -> Result<(), BuryError> {
    let secret_entry = secret_entry()?;
    match secret_entry.delete_credential() {
        Ok(()) | Err(keyring::Error::NoEntry) => {}
        Err(err) => return Err(BuryError::Keychain(err)),
    }

    let cache_entry = derived_key_cache_entry()?;
    match cache_entry.delete_credential() {
        Ok(()) | Err(keyring::Error::NoEntry) => {}
        Err(err) => return Err(BuryError::Keychain(err)),
    }

    info!("Passphrase and cached derived keys removed from Keychain");
    Ok(())
}

fn load_or_prompt_secret() -> Result<SecretString, BuryError> {
    let entry = secret_entry()?;
    match entry.get_password() {
        Ok(secret) => {
            debug!("Loaded passphrase from Keychain");
            Ok(SecretString::new(secret))
        }
        Err(keyring::Error::NoEntry) => {
            let secret = prompt_secret("Passphrase not found. Enter to store: ")?;
            entry.set_password(&secret.value)?;
            Ok(secret)
        }
        Err(err) => Err(BuryError::Keychain(err)),
    }
}

fn prompt_secret(prompt: &str) -> Result<SecretString, BuryError> {
    let secret = rpassword::prompt_password(prompt)?;
    if secret.is_empty() {
        return Err(BuryError::InvalidInput(
            "passphrase cannot be empty".to_string(),
        ));
    }
    Ok(SecretString::new(secret))
}

/// Parse and validate a v1 ciphertext envelope.
///
/// Parameters:
/// - `ciphertext`: The full `bury:v1:<base64(...)>` string.
///
/// Returns:
/// - `Ok(ParsedCiphertext)` with owned salt, nonce, and ciphertext bytes.
/// - `Err(BuryError::InvalidInput)` for malformed prefixes or truncated
///   payloads.
/// - `Err(BuryError::Base64)` when the payload is not valid base64.
///
/// Security considerations:
/// - Parsing happens before any Keychain or crypto work so malformed input
///   fails closed without touching secret material.
fn parse_ciphertext(ciphertext: &str) -> Result<ParsedCiphertext, BuryError> {
    if !ciphertext.starts_with(FORMAT_PREFIX) {
        return Err(BuryError::InvalidInput(
            "invalid ciphertext prefix".to_string(),
        ));
    }

    let payload_b64 = &ciphertext[FORMAT_PREFIX.len()..];
    let payload = base64::engine::general_purpose::STANDARD.decode(payload_b64)?;
    if payload.len() <= SALT_LEN + NONCE_LEN {
        return Err(BuryError::InvalidInput("ciphertext too short".to_string()));
    }

    let mut salt = [0u8; SALT_LEN];
    salt.copy_from_slice(&payload[..SALT_LEN]);

    let mut nonce = [0u8; NONCE_LEN];
    nonce.copy_from_slice(&payload[SALT_LEN..SALT_LEN + NONCE_LEN]);

    Ok(ParsedCiphertext {
        salt,
        nonce,
        ciphertext: payload[SALT_LEN + NONCE_LEN..].to_vec(),
    })
}

/// Attempt decryption using a previously cached derived key, then fall back to
/// passphrase derivation on cache miss or cache mismatch.
///
/// This keeps compatibility with existing `bury:v1:` ciphertexts while making
/// repeated decrypts cheap after the first successful run for a given salt.
///
/// Error handling:
/// - Cache read/parse/store problems are logged and treated as cache misses
///   because the cache is purely a performance optimization.
/// - Authenticated-decryption failures from a cached key trigger a fresh
///   passphrase-derived attempt so stale cache state self-heals.
fn decrypt_ciphertext_with_cache(parsed: &ParsedCiphertext) -> Result<Vec<u8>, BuryError> {
    if let Some(mut cached_key) = try_load_cached_derived_key(&parsed.salt) {
        match decrypt_with_derived_key(parsed, &cached_key) {
            Ok(plaintext) => {
                debug!("Decrypted ciphertext using cached derived key");
                cached_key.zeroize();
                return Ok(plaintext);
            }
            Err(BuryError::DecryptionFailed) => {
                warn!("Cached derived key was stale or invalid; re-deriving from passphrase");
                cached_key.zeroize();
            }
            Err(err) => {
                cached_key.zeroize();
                return Err(err);
            }
        }
    }

    let secret = load_or_prompt_secret()?;
    let mut derived_key = derive_key(secret.as_bytes(), &parsed.salt)?;
    let plaintext = decrypt_with_derived_key(parsed, &derived_key)?;
    try_store_cached_derived_key(parsed.salt, derived_key);
    derived_key.zeroize();
    Ok(plaintext)
}

fn encrypt_secret(plaintext: &[u8], passphrase: &[u8]) -> Result<String, BuryError> {
    let mut salt = [0u8; SALT_LEN];
    OsRng.fill_bytes(&mut salt);

    let mut nonce = [0u8; NONCE_LEN];
    OsRng.fill_bytes(&mut nonce);

    let mut key = derive_key(passphrase, &salt)?;
    let cipher = XChaCha20Poly1305::new_from_slice(&key)
        .map_err(|err| BuryError::Crypto(err.to_string()))?;
    let ciphertext = cipher
        .encrypt(XNonce::from_slice(&nonce), plaintext)
        .map_err(|_| BuryError::DecryptionFailed)?;
    key.zeroize();

    let mut payload = Vec::with_capacity(SALT_LEN + NONCE_LEN + ciphertext.len());
    payload.extend_from_slice(&salt);
    payload.extend_from_slice(&nonce);
    payload.extend_from_slice(&ciphertext);

    let encoded = base64::engine::general_purpose::STANDARD.encode(payload);
    Ok(format!("{FORMAT_PREFIX}{encoded}"))
}

/// Decrypt a parsed ciphertext using a pre-derived symmetric key.
///
/// Parameters:
/// - `parsed`: The validated ciphertext envelope.
/// - `derived_key`: A 32-byte XChaCha20-Poly1305 key.
///
/// Returns:
/// - `Ok(Vec<u8>)` with the plaintext bytes on successful authentication.
/// - `Err(BuryError::DecryptionFailed)` if authentication fails.
/// - `Err(BuryError::Crypto)` if the key length is invalid.
fn decrypt_with_derived_key(
    parsed: &ParsedCiphertext,
    derived_key: &[u8],
) -> Result<Vec<u8>, BuryError> {
    let cipher = XChaCha20Poly1305::new_from_slice(derived_key)
        .map_err(|err| BuryError::Crypto(err.to_string()))?;
    cipher
        .decrypt(
            XNonce::from_slice(&parsed.nonce),
            parsed.ciphertext.as_slice(),
        )
        .map_err(|_| BuryError::DecryptionFailed)
}

/// Compatibility wrapper used by unit tests and non-cached call sites.
///
/// This preserves the original "derive on every decrypt" behavior for direct
/// helper usage while the CLI path now routes through the Keychain-backed cache.
#[cfg(test)]
fn decrypt_secret(ciphertext: &str, passphrase: &[u8]) -> Result<Vec<u8>, BuryError> {
    let parsed = parse_ciphertext(ciphertext)?;
    let mut key = derive_key(passphrase, &parsed.salt)?;
    let result = decrypt_with_derived_key(&parsed, &key);
    key.zeroize();
    result
}

fn derive_key(passphrase: &[u8], salt: &[u8]) -> Result<[u8; 32], BuryError> {
    let params =
        Params::new(64 * 1024, 3, 1, None).map_err(|err| BuryError::Crypto(err.to_string()))?;
    let argon2 = Argon2::new(ARGON2_ALGORITHM, ARGON2_VERSION, params);
    let mut output = [0u8; 32];
    argon2
        .hash_password_into(passphrase, salt, &mut output)
        .map_err(|err| BuryError::Crypto(err.to_string()))?;
    Ok(output)
}

/// Read and decode the derived-key cache, returning an empty cache on missing
/// or malformed state.
///
/// The cache is performance-only, so failures are logged and converted into
/// cache misses rather than aborting encryption or decryption.
fn load_derived_key_cache_records() -> Vec<DerivedKeyCacheRecord> {
    let entry = match derived_key_cache_entry() {
        Ok(entry) => entry,
        Err(err) => {
            warn!(error = %err, "Failed to open derived-key cache entry");
            return Vec::new();
        }
    };

    match entry.get_secret() {
        Ok(bytes) => match deserialize_derived_key_cache(&bytes) {
            Ok(records) => records,
            Err(err) => {
                warn!(reason = %err, "Ignoring malformed derived-key cache");
                Vec::new()
            }
        },
        Err(keyring::Error::NoEntry) => Vec::new(),
        Err(err) => {
            warn!(error = %err, "Failed to load derived-key cache from Keychain");
            Vec::new()
        }
    }
}

/// Look up a previously derived v1 key by salt.
fn try_load_cached_derived_key(salt: &[u8; SALT_LEN]) -> Option<[u8; DERIVED_KEY_LEN]> {
    load_derived_key_cache_records()
        .into_iter()
        .find(|record| &record.salt == salt)
        .map(|record| record.key)
}

/// Persist or refresh a derived v1 key in the Keychain-backed cache.
///
/// Cache writes are best-effort. On failure, the caller still returns the
/// decrypt result because the cache is not required for correctness.
fn try_store_cached_derived_key(salt: [u8; SALT_LEN], key: [u8; DERIVED_KEY_LEN]) {
    let entry = match derived_key_cache_entry() {
        Ok(entry) => entry,
        Err(err) => {
            warn!(error = %err, "Failed to open derived-key cache for writing");
            return;
        }
    };

    let mut records = load_derived_key_cache_records();
    if let Some(existing) = records.iter_mut().find(|record| record.salt == salt) {
        existing.key = key;
    } else {
        records.push(DerivedKeyCacheRecord { salt, key });
    }

    let encoded = serialize_derived_key_cache(&records);
    if let Err(err) = entry.set_secret(&encoded) {
        warn!(error = %err, "Failed to update derived-key cache in Keychain");
    }
}

/// Serialize the derived-key cache into a compact binary format.
///
/// Format:
/// - Magic header: `bury-cache:v1\\0`
/// - Repeated fixed-width records: `salt[16] || key[32]`
fn serialize_derived_key_cache(records: &[DerivedKeyCacheRecord]) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(
        DERIVED_KEY_CACHE_MAGIC.len() + records.len() * DERIVED_KEY_CACHE_RECORD_LEN,
    );
    encoded.extend_from_slice(DERIVED_KEY_CACHE_MAGIC);
    for record in records {
        encoded.extend_from_slice(&record.salt);
        encoded.extend_from_slice(&record.key);
    }
    encoded
}

/// Decode a derived-key cache payload previously produced by
/// [`serialize_derived_key_cache`].
///
/// Returns an error string rather than a hard failure because callers treat the
/// cache as an optimization and should recover by deriving fresh keys when the
/// cache is absent or malformed.
fn deserialize_derived_key_cache(raw: &[u8]) -> Result<Vec<DerivedKeyCacheRecord>, String> {
    if raw.is_empty() {
        return Ok(Vec::new());
    }

    if !raw.starts_with(DERIVED_KEY_CACHE_MAGIC) {
        return Err("missing derived-key cache header".to_string());
    }

    let records_raw = &raw[DERIVED_KEY_CACHE_MAGIC.len()..];
    if records_raw.len() % DERIVED_KEY_CACHE_RECORD_LEN != 0 {
        return Err("derived-key cache length is not aligned to record size".to_string());
    }

    let mut records = Vec::with_capacity(records_raw.len() / DERIVED_KEY_CACHE_RECORD_LEN);
    for chunk in records_raw.chunks_exact(DERIVED_KEY_CACHE_RECORD_LEN) {
        let mut salt = [0u8; SALT_LEN];
        salt.copy_from_slice(&chunk[..SALT_LEN]);

        let mut key = [0u8; DERIVED_KEY_LEN];
        key.copy_from_slice(&chunk[SALT_LEN..]);

        records.push(DerivedKeyCacheRecord { salt, key });
    }

    Ok(records)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encrypt_decrypt_roundtrip() {
        let secret = b"correct horse battery staple";
        let plaintext = b"sk-test-1234";
        let ciphertext = encrypt_secret(plaintext, secret).expect("encrypt");
        let decrypted = decrypt_secret(&ciphertext, secret).expect("decrypt");
        assert_eq!(decrypted, plaintext);
    }

    #[test]
    fn decrypt_fails_with_wrong_secret() {
        let secret = b"secret-a";
        let plaintext = b"top-secret";
        let ciphertext = encrypt_secret(plaintext, secret).expect("encrypt");
        let result = decrypt_secret(&ciphertext, b"secret-b");
        assert!(matches!(result, Err(BuryError::DecryptionFailed)));
    }

    #[test]
    fn decrypt_fails_with_corrupted_ciphertext() {
        let secret = b"secret-a";
        let plaintext = b"top-secret";
        let ciphertext = encrypt_secret(plaintext, secret).expect("encrypt");
        let mut corrupted = ciphertext.clone();
        corrupted.push('A');
        let result = decrypt_secret(&corrupted, secret);
        assert!(result.is_err());
    }

    #[test]
    fn invalid_prefix_rejected() {
        let result = decrypt_secret("not-a-valid-prefix", b"secret");
        assert!(matches!(result, Err(BuryError::InvalidInput(_))));
    }

    #[test]
    fn parse_ciphertext_roundtrip_extracts_payload_parts() {
        let secret = b"correct horse battery staple";
        let plaintext = b"sk-test-1234";
        let ciphertext = encrypt_secret(plaintext, secret).expect("encrypt");
        let parsed = parse_ciphertext(&ciphertext).expect("parse");
        assert_eq!(parsed.salt.len(), SALT_LEN);
        assert_eq!(parsed.nonce.len(), NONCE_LEN);
        assert!(!parsed.ciphertext.is_empty());
    }

    #[test]
    fn derived_key_cache_roundtrip_preserves_records() {
        let records = vec![
            DerivedKeyCacheRecord {
                salt: [1u8; SALT_LEN],
                key: [2u8; DERIVED_KEY_LEN],
            },
            DerivedKeyCacheRecord {
                salt: [3u8; SALT_LEN],
                key: [4u8; DERIVED_KEY_LEN],
            },
        ];
        let encoded = serialize_derived_key_cache(&records);
        let decoded = deserialize_derived_key_cache(&encoded).expect("decode cache");
        assert_eq!(decoded, records);
    }

    #[test]
    fn malformed_derived_key_cache_is_rejected() {
        let invalid = b"bury-cache:v1\0short".to_vec();
        let result = deserialize_derived_key_cache(&invalid);
        assert!(result.is_err());
    }
}
